(() => {
  const {e,icon}=window.UI;
  const {t,content}=window.I18N;
  const {safeUrl,whatsappNumber}=window.PosTools;
  function brand(){
    const c=content().company;
    return '<a class="brand" href="#/" aria-label="'+e(c.name)+' — '+e(t("home"))+'"><span class="brand-logo-frame"><img class="brand-logo" src="'+e(c.logoLight||c.logoFull)+'" alt="" width="1254" height="1254"></span></a>';
  }
  function header(route){
    const config=content(),login=safeUrl(config.company.clientLoginUrl),next=window.I18N.language==="ar"?"en":"ar";
    return '<header class="site-header"><div class="container header-inner">'+brand()+'<nav id="main-nav" aria-label="'+e(t("mainNav"))+'"><a class="'+(route==="home"?"active":"")+'" href="#/">'+t("home")+'</a><a class="'+(route==="about"?"active":"")+'" href="#/about">'+t("about")+'</a><a class="'+(route==="service"?"active":"")+'" href="#/?section=services">'+t("services")+'</a><a href="#/?section=process">'+t("process")+'</a><a href="#/?section=activities">'+t("byBusiness")+'</a><a class="'+(["demos","menuDemo","inventoryDemo","demo"].includes(route)?"active":"")+'" href="#/demos">'+t("work")+'</a><a class="mobile-nav-contact" href="#/contact">'+t("contact")+'</a></nav><div class="header-actions"><button type="button" class="language-switch" data-language="'+next+'" aria-label="'+e(t("switchLang"))+'" title="'+e(t("switchLang"))+'"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/></svg><span lang="'+next+'">'+t("languageLabel")+'</span></button>'+(login?'<a class="client-link" href="'+e(login)+'" target="_blank" rel="noopener noreferrer">'+t("login")+' '+icon("arrowup")+'</a>':'')+'<a class="button button-small button-navy" href="#/contact">'+t("discuss")+' '+icon("arrow")+'</a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="'+e(t("openMenu"))+'">'+icon("menu")+'</button></div></div></header>';
  }
  function footer(){
    const config=content();
    return '<footer class="site-footer"><div class="container footer-main">'+brand()+'<p>'+t("footerLine")+'</p><div><a href="#/about">'+t("about")+'</a><a href="#/?section=services">'+t("services")+'</a><a href="#/demos">'+t("demoHub")+'</a><a href="#/privacy">'+t("privacyLink")+'</a><a href="#/contact">'+t("contact")+'</a></div></div>'+window.CompanyChannels.links("footer")+'<div class="container footer-bottom"><span>© '+new Date().getFullYear()+' <bdi>'+e(config.company.name)+'</bdi>. '+t("copyright")+'</span><span>'+t("footerMade")+' <i class="orange-dot"></i></span></div></footer>';
  }
  function contactForm(service="",activity=""){
    const config=content(),wa=whatsappNumber(config.company.whatsapp);
    return '<form id="contact-form" novalidate><div class="form-header"><span class="form-icon">'+icon("receipt")+'</span><div><h3>'+t("formTitle")+'</h3><p>'+t("formSubtitle")+'</p></div></div><div class="form-grid"><div class="field"><label for="name">'+t("name")+' <span>*</span></label><input id="name" name="name" autocomplete="name" placeholder="'+e(t("namePlaceholder"))+'" minlength="2" maxlength="80" required aria-describedby="name-error"><small class="field-error" id="name-error"></small></div><div class="field"><label for="phone">'+t("phone")+' <span>*</span></label><input id="phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="01xxxxxxxxx" dir="ltr" maxlength="20" required aria-describedby="phone-error"><small class="field-error" id="phone-error"></small></div><div class="field"><label for="activity">'+t("businessType")+' <span>*</span></label><select id="activity" name="activity" required aria-describedby="activity-error"><option value="">'+t("chooseActivity")+'</option>'+config.activities.map(a=>'<option value="'+a.id+'" '+(a.id===activity?'selected':'')+'>'+e(a.title)+'</option>').join("")+'<option value="other" '+(activity==="other"?'selected':'')+'>'+t("otherBusiness")+'</option></select><small class="field-error" id="activity-error"></small></div><div class="field"><label for="service">'+t("requestedService")+' <span>*</span></label><select id="service" name="service" required aria-describedby="service-error"><option value="">'+t("chooseService")+'</option>'+config.services.map(s=>'<option value="'+s.id+'" '+(s.id===service?'selected':'')+'>'+e(s.title)+'</option>').join("")+'</select><small class="field-error" id="service-error"></small></div><div id="service-hint" class="service-selection-hint field-full" hidden aria-live="polite"></div><div class="field field-full"><label for="message">'+t("messageLabel")+' <small>'+t("optional")+'</small></label><div class="brief-prompts" role="group" aria-label="'+e(t("briefLabel"))+'">'+[["briefWebsite","briefSiteLabel"],["briefStore","briefStoreLabel"],["briefSystem","briefSystemLabel"],["briefMenu","briefMenuLabel"]].map(([key,label])=>'<button type="button" data-brief="'+key+'">'+t(label)+'</button>').join("")+'</div><textarea id="message" name="message" rows="3" maxlength="1000" placeholder="'+e(t("messagePlaceholder"))+'"></textarea></div></div><button class="button button-orange form-submit" type="submit">'+t(wa?"continueWhatsapp":"prepareRequest")+' '+icon(wa?"whatsapp":"arrow")+'</button><p class="form-note">'+icon("shield")+t(wa?"formWhatsappNote":"formDraftNote")+'</p><div id="request-result" class="request-result" hidden aria-live="polite"></div></form>';
  }
  function contactSection(service="",activity="",standalone=false){
    return '<section class="contact-section '+(standalone?'standalone-contact':'')+'" id="contact"><div class="container contact-layout"><div class="contact-copy"><span class="eyebrow">'+t("contactKicker")+'</span><h2>'+t("contactTitle1")+'<br>'+t("contactTitle2")+' <span class="orange-text">'+t("contactTitleAccent")+'</span></h2><p>'+t("contactIntro")+'</p><ul class="contact-points">'+["contactPoint1","contactPoint2","contactPoint3"].map(k=>'<li>'+icon("check")+t(k)+'</li>').join("")+'</ul>'+window.CompanyChannels.links()+window.WhatsApp.card()+'</div><div class="contact-form-card">'+contactForm(service,activity)+'</div></div></section>';
  }
  function service(s){
    const demoPath={pos:"/demo",menu:"/demos/menu",erp:"/demos/inventory"}[s.id];
    return '<main id="main"><section class="detail-hero"><div class="container"><div class="breadcrumb"><a href="#/">'+t("home")+'</a>'+icon("chevron")+'<a href="#/?section=services">'+t("allServices")+'</a>'+icon("chevron")+'<span>'+e(s.title)+'</span></div><div class="detail-hero-grid"><div><span class="eyebrow">'+e(s.tag)+'</span><h1>'+e(s.title)+'</h1><p>'+e(s.description)+'</p><div class="hero-actions"><a class="button button-orange" href="#/contact?service='+s.id+'">'+t("discuss")+' '+icon("arrow")+'</a>'+(demoPath?'<a class="button button-outline" href="#'+demoPath+'">'+t("tryDemo")+'</a>':'')+'</div></div><div class="detail-visual detail-'+s.id+'">'+window.Studio.graphic(s.id)+'<div class="detail-icon">'+icon(s.icon)+'</div><span>'+e(s.tag)+'</span><div class="detail-chips">'+s.features.slice(0,3).map(f=>'<span>'+icon("check")+e(f[0])+'</span>').join("")+'</div></div></div></div></section><section class="section"><div class="container service-detail-layout"><aside class="audience-card"><span class="eyebrow">'+t("serviceAudience")+'</span><h2>'+t("serviceAudienceTitle")+'</h2><ul>'+s.audience.map(a=>'<li>'+icon("check")+e(a)+'</li>').join("")+'</ul><p>'+t("serviceScope")+'</p><a href="#/contact?service='+s.id+'" class="text-link">'+t("tellBusiness")+' '+icon("arrow")+'</a></aside><div><span class="eyebrow">'+t("serviceFeatures")+'</span><h2>'+t("serviceFeaturesTitle")+'</h2><div class="features-list">'+s.features.map((f,i)=>'<article><span>0'+(i+1)+'</span><div><h3>'+e(f[0])+'</h3><p>'+e(f[1])+'</p></div>'+icon("check")+'</article>').join("")+'</div></div></div></section><section class="service-cta"><div class="container"><div><h2>'+t("serviceCtaTitle")+'</h2><p>'+t("serviceCtaDesc")+'</p></div><a class="button button-orange" href="#/contact?service='+s.id+'">'+t("serviceQuote")+' '+icon("arrow")+'</a></div></section><section class="section related-section"><div class="container"><h2>'+t("relatedServices")+'</h2><div class="related-links">'+content().services.filter(x=>x.id!==s.id).map(x=>'<a href="#/services/'+x.id+'">'+icon(x.icon)+'<b>'+e(x.title)+'</b>'+icon("arrow")+'</a>').join("")+'</div></div></section></main>';
  }
  function demo(){
    return '<main id="main" class="demo-main"><div class="container">'+window.Experiences.nav("pos")+'<div class="breadcrumb"><a href="#/">'+t("home")+'</a>'+icon("chevron")+'<span>'+t("demoCrumb")+'</span></div><div class="demo-heading"><div><span class="eyebrow">'+t("tryIt")+'</span><h1>'+t("demoHeading")+'</h1><p>'+t("demoIntro")+'</p></div><button class="button button-outline reset-demo">'+icon("refresh")+' '+t("reset")+'</button></div><div class="demo-notice">'+icon("info")+'<span>'+t("demoNotice")+'</span><span class="live-badge"><i></i>'+t("browserLocal")+'</span></div><div class="pos-layout"><section class="catalog-panel" aria-labelledby="catalog-title"><div class="catalog-heading"><h2 id="catalog-title">'+icon("box")+' '+t("products")+'</h2><span>'+t("sampleProducts",{count:content().demoProducts.length.toLocaleString(window.I18N.locale)})+'</span></div><div class="search-field">'+icon("search")+'<input type="search" id="product-search" aria-label="'+e(t("searchLabel"))+'" placeholder="'+e(t("searchPlaceholder"))+'" autocomplete="off"><kbd>'+t("search")+'</kbd></div><div class="category-tabs" aria-label="'+e(t("products"))+'"><button class="selected" data-category="الكل" aria-pressed="true">'+t("allProducts")+'</button><button data-category="أغذية" aria-pressed="false">'+t("food")+'</button><button data-category="مشروبات" aria-pressed="false">'+t("beverages")+'</button></div><div id="products" class="products-grid"></div><p class="inventory-note">'+icon("info")+' '+t("inventoryNote")+'</p></section><section class="invoice-panel" aria-labelledby="invoice-title"><div class="invoice-heading"><span class="invoice-icon">'+icon("receipt")+'</span><div><h2 id="invoice-title">'+t("invoice")+'</h2><small>'+t("sampleSale")+'</small></div><span id="cart-count" class="count-badge">0</span></div><div id="cart-lines"></div><div class="invoice-total"><div><span>'+t("itemCount")+'</span><b id="item-count">0</b></div><div class="grand-total"><span>'+t("total")+'</span><b id="cart-total">0</b></div><small>'+t("pricesNote")+'</small><button class="button button-orange checkout-button" id="checkout" disabled>'+t("checkout")+' '+icon("check")+'</button><p>'+icon("shield")+' '+t("noPayment")+'</p></div><button class="last-receipt" id="last-receipt" hidden>'+icon("receipt")+' '+t("lastReceipt")+'</button></section></div><div class="demo-contact-strip"><div>'+icon("monitor")+'<span><b>'+t("demoCtaTitle")+'</b> '+t("demoCtaDesc")+'</span></div><a class="text-link" href="#/contact?service=pos">'+t("customDemo")+' '+icon("arrow")+'</a></div></div></main>';
  }
  function missing(){
    return '<main id="main" class="not-found container"><span class="eyebrow">404</span><h1>'+t("notFoundTitle")+'</h1><p>'+t("notFoundIntro")+'</p><a href="#/" class="button button-orange">'+t("backHome")+' '+icon("arrow")+'</a></main>';
  }
  window.Views={header,footer,service,demo,contactSection,brand,contact:(s,a)=>'<main id="main">'+contactSection(s,a,true)+'</main>',missing};
})();